"""Thumbnails of images in galleries."""

from __future__ import annotations

import posixpath
from pathlib import Path
from typing import TYPE_CHECKING, NamedTuple

from PIL import Image

from .. import deps
from . import save

if TYPE_CHECKING:
    from ..model.resource import Resource

PREFIX = "thumb_"
HEIGHT = 150


class Thumb(NamedTuple):
    path: str
    width: int
    height: int


def path(image: Resource) -> str:
    return posixpath.join(posixpath.dirname(image.path), PREFIX + image.name)


def info(image: Resource) -> Thumb:
    """Thumbnail of an image resource, generated by its own task."""
    thumb = path(image)
    raw = image.site.raw(thumb.removeprefix("media/"))
    deps.record_file(raw)
    with Image.open(raw) as im:
        return Thumb(thumb, im.size[0], im.size[1])


def make(source: Path, target: Path) -> None:
    im = Image.open(source)
    width = im.size[0] * HEIGHT // im.size[1] + 1
    im.thumbnail((width, HEIGHT), Image.Resampling.LANCZOS)
    save(im, target)
